<?php 
$color_theme = 'blue-brown';

if ( is_front_page() ) {
  $color_theme = 'blue-brown';
} else if ( is_post_type_archive() ) {
  $post_type = get_query_var( 'post_type' );
  
  switch ( $post_type ) {
    case 'boardgame':
      $color_theme = 'yellow-green';
      break;
    case 'event':
      $color_theme = 'blue-brown';
      break;
    default:
      $color_theme = 'green-white';
  }
} else if ( is_singular() ) {
  $color_theme = 'green-white';
}


